import React, { useEffect, useState } from "react";
import type { SupportNote } from "../../features/admin/types";
import { AdminLayout } from "../../features/admin/components/AdminLayout";
import { listAllNotes } from "../../sessionServices/support/supportNotesService";
import { graphql, navigate } from "gatsby";

type NoteWithId = SupportNote & { id: string };

export default function SupportPage() {
  const [notes, setNotes] = useState<NoteWithId[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    listAllNotes()
      .then(setNotes)
      .finally(() => setLoading(false));
  }, []);

  return (
    <AdminLayout title="Support notes">
      {loading ? (
        <div className="flex items-center justify-center py-16">
          <div className="h-6 w-6 animate-spin rounded-full border-4 border-gray-300 border-t-gray-800" />
        </div>
      ) : notes.length === 0 ? (
        <div className="rounded-xl bg-white py-12 text-center ring-1 ring-gray-200">
          <p className="text-sm text-gray-500">No internal notes yet.</p>
        </div>
      ) : (
        <div className="overflow-hidden rounded-xl bg-white shadow-sm ring-1 ring-gray-200">
          <table className="min-w-full divide-y divide-gray-100">
            <thead>
              <tr className="bg-gray-50">
                <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Note</th>
                <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Itinerary</th>
                <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Date</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {notes.map((n) => (
                <tr key={n.id} className="hover:bg-gray-50">
                  <td className="max-w-sm px-4 py-3 text-sm text-gray-800">{n.note}</td>
                  <td className="px-4 py-3">
                    <button
                      onClick={() => navigate(`/admin/itineraries/${n.itineraryId}`)}
                      className="text-xs text-gray-500 underline hover:text-gray-900"
                    >
                      {n.itineraryId.slice(0, 8)}…
                    </button>
                  </td>
                  <td className="px-4 py-3 text-xs text-gray-400">{formatTs(n.createdAt)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </AdminLayout>
  );
}

function formatTs(ts: unknown): string {
  try {
    return (ts as { toDate: () => Date }).toDate().toLocaleString("en-CA");
  } catch {
    return "—";
  }
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;